-- Test only an explicitly marked disposable database. Test data are synthetic.
DO $$ BEGIN
 IF current_database() NOT IN ('b21_correction_test','b21_correction_final2','b21_correction_final3','b21_fresh_review') OR NOT EXISTS(SELECT 1 FROM b21_guard.marker WHERE id='mgl850-b21-correction') THEN RAISE EXCEPTION 'Refusing unsafe database'; END IF;
END $$;
CREATE FUNCTION pg_temp.reject_expected(statement text, expected_state text, expected_message text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN
  IF SQLSTATE<>expected_state OR SQLERRM<>expected_message THEN RAISE; END IF;
  RAISE NOTICE 'PASS: %', expected_message; RETURN;
 END;
 RAISE EXCEPTION 'statement unexpectedly succeeded';
END $$;
